#include <stdio.h>
#include <stdint.h>
#include <stddef.h>
struct fiemap_extent {uint64_t fe_logical,fe_length;};
struct fiemap {unsigned int fm_mapped_extents;struct fiemap_extent fm_extents[1];};
struct fiemap_extent *get_extent(struct fiemap *fiemap, size_t loff,
				 unsigned int *index)
{
	struct fiemap_extent *extent;
	size_t ext_end_off;

	for (unsigned int i = 0; i < fiemap->fm_mapped_extents; i++) {
		extent = &fiemap->fm_extents[i];
		ext_end_off = extent->fe_logical + extent->fe_length - 1;
		if (ext_end_off < loff)
			continue;

		if (index)
			*index = i;

		return extent;
	}
	return NULL;
}
int main(void){struct fiemap f={1,{{4096,4096}}};unsigned int idx=99;struct fiemap_extent *p=get_extent(&f,0,&idx);printf("hole_offset=0 returned_extent_start=%llu index=%u covers_requested_offset=%d\n",p?(unsigned long long)p->fe_logical:0,idx,p&&p->fe_logical<=0);return 0;}
